const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const fileName = $('Ensamblaje HTML').first().json.file_name || 'CV_Ezequiel.pdf';

return {
  json: {
    success: true,
    url_pdf: `data:application/pdf;base64,${buffer.toString('base64')}`,
    file_name: fileName
  }
};

let template = `<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <title>CV - {{nombre_completo}} | {{titulo_adaptado}}</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Montserrat:ital,wght@0,400;0,600;0,700;1,400&display=swap');
        @page { size: A4; margin: 1cm; }
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { font-family: 'Montserrat', sans-serif; font-size: 9.5pt; line-height: 1.5; color: #111; background-color: #fff; }

        .header-container { display: flex; align-items: center; text-align: center; margin-bottom: 8px; }
        .header-container::before, .header-container::after { content: ''; flex: 1; border-bottom: 2px solid #000; }
        .header-container::before { margin-right: 15px; }
        .header-container::after { margin-left: 15px; }

        h1 { font-size: 18pt; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; white-space: nowrap; }

        .profile-desc { text-align: center; font-size: 10.5pt; font-style: italic; margin-bottom: 10px; padding: 0 10px; }

        .section-title { display: flex; align-items: center; text-align: center; margin-top: 15px; margin-bottom: 15px; }
        .section-title::before, .section-title::after { content: ''; flex: 1; border-bottom: 2px solid #000; }
        .section-title::before { margin-right: 15px; }
        .section-title::after { margin-left: 15px; }
        .section-title h2 { font-size: 14pt; font-weight: 700; text-transform: uppercase; white-space: nowrap; }

        .contact-info { text-align: center; font-size: 10pt; font-weight: 600; margin-bottom: 10px; }
        .contact-info a { color: #0056b3; text-decoration: none; }

        .experience-item { margin-bottom: 12px; }
        .experience-header { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 4px; }
        .experience-header .company { font-weight: 700; font-size: 11pt; }
        .experience-header .dates { font-size: 10.5pt; }
        .experience-subheader { font-weight: 600; margin-bottom: 6px; }

        ul { list-style-type: disc; padding-left: 20px; }
        li { margin-bottom: 4px; line-height: 1.5; }

        .education-item { margin-bottom: 10px; }
        .education-header { display: flex; justify-content: space-between; align-items: baseline; }
        .education-header .inst { font-weight: 600; }
        .education-header .dates { font-size: 10.5pt; }
        .education-subheader { font-weight: 700; margin-bottom: 4px; }
        .education-details { padding-left: 20px; font-size: 10pt; }

        .skills-section p { text-align: center; font-size: 10.5pt; line-height: 1.8; }
        .skills-section strong { font-weight: 700; }
    </style>
</head>
<body>
    <div class="header-container">
        <h1>{{nombre_completo}}</h1>
    </div>
    <div class="profile-desc">
        {{resumen_perfil}}
    </div>

    <div class="section-title"><h2>CONTACTO</h2></div>
    <div class="contact-info">
        <a href="https://{{github_url}}">{{github_url}}</a> - {{ciudad}} - <a href="mailto:{{email}}">{{email}}</a> - <a href="{{portfolio_url}}">{{portfolio_url}}</a>
    </div>

    <div class="section-title"><h2>EXPERIENCIA PROFESIONAL</h2></div>
    {{experiencias_html}}

    <div class="section-title"><h2>EDUCACIÓN</h2></div>
    {{educacion_html}}

    <div class="section-title"><h2>HABILIDADES Y TÉCNICAS</h2></div>
    <div class="skills-section">
        <p>{{skills_html}}</p>
    </div>
</body>
</html>`;

// ===================== PARSER ROBUSTO v2 =====================
// Cloudflare puede devolver el JSON en 3 lugares distintos según el modelo:
//   A) result.response  → OBJETO ya parseado (llama-3.3-70b-json)
//   B) result.response  → STRING con JSON embebido (llama-3-8b-instruct clásico)
//   C) choices[0].message.content → STRING formato OpenAI-compatible
// Este parser cubre los 3 casos sin romperse.

function extractCvData(input) {
    // Caso A: ya es objeto
    if (input && typeof input === 'object' && !Array.isArray(input)) {
        return input;
    }
    // Caso B/C: es string con posible basura alrededor
    if (typeof input === 'string') {
        let s = input.replace(/```json/gi, '').replace(/```/gi, '').trim();
        const fb = s.indexOf('{');
        const lb = s.lastIndexOf('}');
        if (fb !== -1 && lb !== -1 && lb > fb) {
            s = s.substring(fb, lb + 1);
        }
        return JSON.parse(s);
    }
    throw new Error('Tipo no soportado: ' + typeof input);
}

let cvData = null;
const nodeData = $input.first().json;

try {
    if (nodeData.success === false) {
        throw new Error('Cloudflare AI devolvió success=false: ' + JSON.stringify(nodeData.errors || nodeData.messages));
    }

    if (nodeData.result && nodeData.result.response !== undefined && nodeData.result.response !== null) {
        // Formato estándar Workers AI (objeto u string, da igual)
        cvData = extractCvData(nodeData.result.response);
    } else if (nodeData.choices && nodeData.choices[0] && nodeData.choices[0].message && nodeData.choices[0].message.content) {
        // Formato OpenAI-compatible
        cvData = extractCvData(nodeData.choices[0].message.content);
    } else if (nodeData.response !== undefined) {
        // Response a nivel raíz
        cvData = extractCvData(nodeData.response);
    } else {
        throw new Error('Estructura de respuesta de Cloudflare no reconocida');
    }

    // Sanity check: debe traer al menos experiencias o título
    if (!cvData.experiencias && !cvData.titulo_adaptado) {
        throw new Error('JSON parseado no tiene estructura esperada. Keys: ' + Object.keys(cvData).join(','));
    }

    console.log('✅ CV parseado OK. Título:', cvData.titulo_adaptado, '| Experiencias:', (cvData.experiencias || []).length);
} catch (error) {
    console.warn('⚠️ Fallback activado. Motivo:', error.message);
    cvData = {
        titulo_adaptado: 'Software Developer',
        resumen_perfil: 'Profesional con sólida formación en desarrollo de software, informática y sistemas. Enfoque en arquitectura de alta disponibilidad, backend autoalojado y optimización de datos.',
        experiencias: [],
        educacion: [],
        skills_agrupadas: 'Backend: Supabase, PostgreSQL, Django | Frontend: Angular, React, Tailwind | DevOps: Docker, Cloudflare, Linux'
    };
}

const webhookBody = $('Webhook').first().json?.body || {};
const userProfile = webhookBody.profile || {};
const persona = {
  nombre_completo: userProfile.name || 'Ezequiel Enrico Areco',
  ciudad: userProfile.location || 'Marcos Paz, Buenos Aires, Argentina',
  email: userProfile.email || 'ezequielenrico15@gmail.com',
  telefono: userProfile.phone || '+54 11 1234-5678',
  linkedin_url: userProfile.linkedin || 'https://www.linkedin.com/in/ezequiel-areco',
  github_url: userProfile.github || 'github.com/arecofix',
  portfolio_url: userProfile.portfolio || 'https://portfolio.arecofix.com.ar'
};

// ===================== ARMADO DE HTML =====================
let expHtml = '';
if (Array.isArray(cvData.experiencias)) {
    cvData.experiencias.forEach(exp => {
        const bullets = Array.isArray(exp.bullets) ? exp.bullets : [];
        const bulletsHtml = bullets.map(b => `<li>${b}</li>`).join('');
        expHtml += `<div class="experience-item">
            <div class="experience-header">
                <span class="company">${exp.empresa || ''}</span>
                <span class="dates">${(exp.fechas || '').replace(/[^0-9 -Actualidad]/g, '').substring(0,25)}</span>
            </div>
            <div class="experience-subheader">${exp.puesto || ''}</div>
            <ul>${bulletsHtml}</ul>
        </div>`;
    });
}

let eduHtml = '';
if (Array.isArray(cvData.educacion)) {
    cvData.educacion.forEach(edu => {
        eduHtml += `<div class="education-item">
            <div class="education-header">
                <span class="inst">${edu.institucion_y_anio ? edu.institucion_y_anio.split('|')[0] : ''}</span>
                <span class="dates">${edu.institucion_y_anio ? edu.institucion_y_anio.split('|')[1] : ''}</span>
            </div>
            <div class="education-subheader">${edu.titulo || ''}</div>
            <div class="education-details">${edu.detalles || ''}</div>
        </div>`;
    });
}

template = template.replace('{{titulo_adaptado}}', cvData.titulo_adaptado || '');
template = template.replace('{{resumen_perfil}}', cvData.resumen_perfil || '');
template = template.replace('{{experiencias_html}}', expHtml);
template = template.replace('{{educacion_html}}', eduHtml);
template = template.replace('{{skills_html}}', (cvData.skills_agrupadas || '').replace(/(Frontend:|Backend:|DevOps:|Idiomas:|Languages:|Databases:)/g, '<strong>$1</strong>'));

template = template.replace(/{{nombre_completo}}/g, persona.nombre_completo);
template = template.replace(/{{ciudad}}/g, persona.ciudad);
template = template.replace(/{{email}}/g, persona.email);
template = template.replace(/{{telefono}}/g, persona.telefono);
template = template.replace(/{{linkedin_url}}/g, persona.linkedin_url);
template = template.replace(/{{github_url}}/g, persona.github_url);
template = template.replace(/{{portfolio_url}}/g, persona.portfolio_url);

const buffer = Buffer.from(template, 'utf-8');
const tituloSlug = (cvData.titulo_adaptado || 'CV').replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');

return {
  json: {
    html_final: template,
    file_name: `Ezequiel_Enrico_${tituloSlug}_CV.pdf`,
    debug_titulo: cvData.titulo_adaptado,
    debug_num_experiencias: (cvData.experiencias || []).length,
    debug_num_educacion: (cvData.educacion || []).length
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    }
  }
};

// ============ DATOS DE SUPABASE (FALLBACK) ============
const experiencia = $('Supabase Experiencia').all().map(i => i.json).filter(i => i && i.id);
const educacion_raw = $('Supabase Educacion').all().map(i => i.json).filter(i => i && i.id);

let finalExperiencias = [...new Map(experiencia.map(item => {
  const s = item.fecha_inicio ? item.fecha_inicio.substring(0,4) : '';
  const e = (!item.fecha_fin || item.fecha_fin === 'null') ? 'Actualidad' : item.fecha_fin.substring(0,4);
  return { id: item.id, empresa: item.empresa, puesto: item.puesto_base, fechas: s + ' - ' + e, bullets: item.bullet_points || [] };
})).values()];

const uniqueEducacionRaw = [...new Map(educacion_raw.map(item => [item.id, item])).values()];
let educacion = uniqueEducacionRaw.filter(e => e.tipo === 'educacion').map(e => {
  const s = e.detalles && e.detalles.fecha_inicio ? e.detalles.fecha_inicio.substring(0,4) : '';
  const f = e.detalles && e.detalles.fecha_fin ? e.detalles.fecha_fin.substring(0,4) : (e.detalles && e.detalles.fechas ? e.detalles.fechas : 'Actualidad');
  return { titulo: e.titulo, institucion_y_anio: e.institucion + ' | ' + (s ? s + '-' + f : f), detalles: e.detalles?.proyectos || '' };
});
const skillsRaw = uniqueEducacionRaw.filter(e => e.tipo === 'skill');
const certRaw = uniqueEducacionRaw.filter(e => e.tipo === 'certificacion');

let skillsStr = skillsRaw.map(s => JSON.stringify(s.detalles)).join(' | ');
let certStr = certRaw.map(c => c.titulo).join(', ');

// ============ DATOS DEL FRONTEND (SOBREESCRIBEN SUPABASE) ============
const webhookBody = $('Webhook').first().json?.body || {};
const userProfile = webhookBody.profile || null;

if (userProfile) {
  if (userProfile.experiences && userProfile.experiences.length > 0) {
    finalExperiencias = userProfile.experiences.map((exp, i) => {
      const startYear = exp.start ? exp.start.toString().substring(0,4) : '';
      const endYear = (!exp.end || exp.end === 'null' || exp.end === '') ? 'Actualidad' : exp.end.toString().substring(0,4);
      return { empresa: exp.company, puesto: exp.role, fechas: startYear + ' - ' + endYear, bullets: [exp.description] };
    });
  }
  if (userProfile.educations && userProfile.educations.length > 0) {
    educacion = userProfile.educations.map((edu, i) => {
      const startYear = edu.start ? edu.start.toString().substring(0,4) : '';
      const endYear = (!edu.end || edu.end === 'null' || edu.end === '') ? 'Actualidad' : edu.end.toString().substring(0,4);
      return { titulo: edu.degree, institucion_y_anio: edu.institution + ' | ' + startYear + '-' + endYear, detalles: '' };
    });
  }
  if (userProfile.skills || userProfile.languages) {
    skillsStr = (userProfile.skills || '') + ' | Idiomas: ' + (userProfile.languages || '');
  }
}

// ============ MASTER CV FINAL ============
const master_cv = {
  experiencia_laboral: finalExperiencias,
  educacion: educacion,
  skills: skillsStr,
  certificaciones: certStr
};

const job_description = webhookBody.job_description || 'Desarrollador de Software';

// ============ PROMPT MEGA-ESTRICTO ============
const systemPrompt = 'Eres un experto en ATS. DEBES generar un objeto JSON. ESTÁ PROHIBIDO GENERAR MÁS DE UNA PÁGINA DE CONTENIDO.';

const userPrompt = [
  'Adapta mi perfil a la oferta laboral bajo pena de fallo si incumples alguna regla:',
  'REGLA 1 (LONGITUD EXTREMA): El CV final será impreso en UNA (1) sola carilla A4. Por lo tanto, los bullets de las experiencias deben ser MÁXIMO 1 o 2 líneas. Si te pasas, arruinarás el diseño.',
  'REGLA 2 (PALABRAS CLAVE): DEBES leer las tecnologías requeridas en la Oferta de Trabajo e incluirlas explícitamente en el "resumen_perfil" y en "skills_agrupadas" (ej: Rust, React, etc.) SÓLO si tienen relación con mi perfil.',
  'REGLA 3 (MANTENER EXPERIENCIAS Y EDUCACIÓN): Incluye TODAS las (' + finalExperiencias.length + ') experiencias y TODAS las (' + educacion.length + ') educaciones pasadas en el JSON. No descartes la Tecnicatura ni nada, simplemente haz sus detalles muy cortos.',
  'REGLA 4 (IDENTIDAD): Nombre: Ezequiel Enrico Areco. No cambies nombres de empresas ni fechas.',
  'FORMATO DE SALIDA (JSON PURO):',
  '{',
  '  "titulo_adaptado": "TÍTULO EXACTO DE LA OFERTA",',
  '  "resumen_perfil": "Resumen ultracorto (max 2 oraciones) usando las palabras clave principales de la oferta.",',
  '  "experiencias": [ { "empresa": "...", "fechas": "...", "puesto": "...", "bullets": ["bullet corto 1"] } ],',
  '  "educacion": [ { "titulo": "...", "institucion_y_anio": "...", "detalles": "..." } ],',
  '  "skills_agrupadas": "Skills estratégicas incluyendo las de la oferta laboral (Frontend:... Backend:...)"',
  '}',
  '=== OFERTA ===',
  job_description,
  '=== MASTER CV ===',
  JSON.stringify(master_cv)
].join('\n');

const ai_payload = {
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  max_tokens: 3000,
  temperature: 0.1,
  response_format: { type: 'json_object' }
};

return { json: { master_cv, job_description, ai_payload } };
